const input = $input.first().json;
const body = input.body || input;
// Payload chuẩn hóa từ NestJS SlackService (Socket Mode) — hoặc WF01 Router test payload
const userId = body.sender?.id || body.user_id || body.userId || body.employeeId || "guest";
const raw = body.message?.text || (typeof body.message === 'string' ? body.message : '') || body.originalMessage || body.maskedMessage || "";
if (!raw) return [];
const masked = body.maskedMessage || raw;
const slackChannel = body.slackChannel || null;
const threadTs = body.threadTs || null;
return [{ json: { userId, message: masked, originalMessage: raw, channel: body.channel || "zalo", externalId: userId, slackChannel, threadTs } }];

// [PII Masking] WF04 — dùng lại đúng regex của WF01 Router (doc 11: CCCD/CMND, SĐT VN, email).
// LLM/Chat Memory CHỈ thấy bản masked; bản original vẫn được lưu DB để đối chiếu audit.
const p = $input.first().json;
const raw = String(p.message || p.originalMessage || "");
const masked = raw
  .replace(/\b(\d{9}|\d{12})\b/g, "[MASKED_ID]")
  .replace(/\b(0[35789]\d{8})\b/g, "[MASKED_PHONE]")
  .replace(/[\w.-]+@[\w.-]+\.\w+/g, "[MASKED_EMAIL]");
return [{ json: { ...p, message: masked, maskedMessage: masked } }];

const output = $input.first().json.output || "";
const session = $("Get/Create CSKH Session").first().json;
const parsedMsg = $("Parse Zalo Message").first().json;
const userId = parsedMsg.userId;
const userMsg = parsedMsg.originalMessage;
const slackChannel = parsedMsg.slackChannel || null;
const threadTs = parsedMsg.threadTs || null;
const escalateMatch = output.match(/\[CAN_ESCALATE:\s*([^\]]+)\]/);
const shouldEscalate = !!escalateMatch;
const escalateReason = escalateMatch ? escalateMatch[1].trim() : null;
const answer = output.replace(/\[CAN_ESCALATE:[^\]]*\]/, '').trim() || "Xin lỗi, vui lòng thử lại sau.";
return [{ json: { answer, shouldEscalate, escalateReason, sessionId: session.id, userId, userMessage: userMsg, slackChannel, threadTs } }];
